ContextualCollectionMembers.scan_body:
if ($context->firstBatch) { $this->reset(); $this->started = true; }
$this->complete = false;
if (! $this->started) { $this->failed = true; return; }
foreach ($context->files as $file) {
    $this->cancellation($context);
    if ($this->failed) { break; }
    $path = $this->path($file->path);
    $this->bytes += strlen($file->contents);
    if (strlen($file->contents) > 2_000_000 || $this->bytes > 67_108_864 || count($this->sources) >= 100_000
        || array_key_exists($path, $this->sources)) { $this->failed = true; break; }
    $this->sources[$path] = hash('sha256', $file->contents);
    try {
        $nodes = CodebaseScanSyntax::parse($file->contents);
    } catch (\PhpParser\Error) { $this->failed = true; break; }
    $candidates = [];
    foreach (self::scopes($nodes) as [$owner, $scope]) {
        foreach (self::candidates($scope) as $proof) {
            $proof['file'] = $path;
            $proof['owner'] = $owner;
            $proof['scope'] = $scope;
            $site = $proof['fetch']->getStartFilePos().':'.($proof['fetch']->getEndFilePos() + 1);
            if ($this->fileMemberCount >= 100_000) { $this->failed = true; break 2; }
            $this->fileMemberCount++;
            $this->fileMembers[$path][$site] = array_key_exists($site, $this->fileMembers[$path] ?? [])
                ? null : $proof;
            foreach (self::keys($proof['fetch']) as $key) { $candidates[$key] = $proof; }
        }
    }
    // A property provider has no file field. Every property syntax reserves its spans.
    foreach ((new NodeFinder)->find($nodes, static fn (Node $node): bool =>
        $node instanceof Node\Expr\PropertyFetch || $node instanceof Node\Expr\NullsafePropertyFetch
        || $node instanceof Node\Expr\StaticPropertyFetch) as $fetch) {
        $this->cancellation($context);
        foreach (self::keys($fetch) as $key) {
            if (count($this->members) >= 100_000) { $this->failed = true; break 2; }
            $this->members[$key] = array_key_exists($key, $this->members) ? null : ($candidates[$key] ?? null);
        }
    }
}
if ($this->failed) { $this->members = $this->fileMembers = []; }
$this->complete = $context->lastBatch && ! $this->failed;

ForwardedTransactionTemplateCalls.scan_body:
if ($context->firstBatch) { $this->reset(); $this->started = true; }
$this->complete = false;
if (! $this->started) { $this->failed = true; return; }
try {
    foreach ($context->files as $file) {
        $context->cancellation->throwIfCancelled();
        if ($this->failed) { break; }
        $path = $this->path($file->path);
        $this->bytes += strlen($file->contents);
        if (strlen($file->contents) > 2_000_000 || $this->bytes > 67_108_864 || count($this->sources) >= 100_000
            || array_key_exists($path, $this->sources)) { $this->failed = true; break; }
        $this->sources[$path] = hash('sha256', $file->contents);
        try {
            $nodes = CodebaseScanSyntax::parse($file->contents);
        } catch (\PhpParser\Error) { $this->failed = true; break; }
        // A framework-default dispatch is supplemented only without visible replacements.
        foreach ((new NodeFinder)->findInstanceOf($nodes, Node\Expr\StaticCall::class) as $dispatch) {
            if (! $dispatch->class instanceof Node\Name || ! in_array(strtolower($dispatch->class->toString()), [
                'illuminate\\support\\facades\\db', 'illuminate\\database\\databasemanager', 'illuminate\\database\\connection',
            ], true)) { continue; }
            if ($dispatch->name instanceof Node\Identifier && strtolower($dispatch->name->name) === 'extend') {
                $this->connectionExtensions = true;
            }
            if (! $dispatch->name instanceof Node\Identifier || in_array(strtolower($dispatch->name->name), [
                'macro', 'mixin', 'swap', 'setfacadeapplication', 'shouldreceive', 'expects', 'spy', 'partialmock',
            ], true)) { $this->macroReplacement = true; }
        }
        foreach ((new NodeFinder)->findInstanceOf($nodes, Node\Expr\MethodCall::class) as $dispatch) {
            if ($dispatch->name instanceof Node\Identifier && in_array(strtolower($dispatch->name->name), ['macro', 'mixin'], true)) {
                $this->macroReplacement = true;
            }
        }
        $eligible = [];
        foreach (self::scopes($nodes) as [$owner, $scope]) {
            foreach (self::candidates($scope) as $proof) {
                $proof += ['owner' => $owner, 'scope' => $scope, 'file' => $path];
                $eligible[self::key($proof['call'])] = $proof;
            }
        }
        // Invocation contexts have no file. Incompatible calls reserve the same spans too.
        foreach ((new NodeFinder)->find($nodes, static fn (Node $node): bool =>
            $node instanceof Node\Expr\CallLike) as $call) {
            $context->cancellation->throwIfCancelled();
            if (count($this->calls) >= 100_000) { $this->failed = true; break; }
            $key = self::key($call);
            $this->calls[$key] = array_key_exists($key, $this->calls) ? null : ($eligible[$key] ?? null);
        }
    }
} catch (\Throwable $error) { $this->failed = true; $this->complete = false; $this->calls = []; throw $error; }
if ($this->failed) { $this->calls = []; }
$this->complete = $context->lastBatch && ! $this->failed;

FactoryResultContract.scan_body:
CodebaseScanSyntax::registerProjection(self::class.'::all-mapping', self::allMapping(...));
CodebaseScanSyntax::registerProjection(self::class.'::outside-class-mapping', self::outsideMapping(...));
if ($context->firstBatch) {
    $this->source = new PhpSource($this->source->root);
    $this->analyzedSources = [];
    $this->scanFailed = false;
    $this->native = null;
    $this->standardFactories = [];
    $this->mappingConfigured = false;
}
$this->scanStarted = true;
$this->scanComplete = false;
foreach ($context->files as $file) {
    $context->cancellation->throwIfCancelled();
    $path = $this->path($file->path);
    $this->analyzedSources[$path] = array_key_exists($path, $this->analyzedSources)
        ? null : hash('sha256', $file->contents);
    if (! $this->mappingConfigured) {
        if (strlen($file->contents) > 2_000_000) {
            $this->scanFailed = true;
            break;
        }
        try {
            // Native setter declarations do not execute during inclusion.
            // Actual top-level configuration in a native host file still poisons the proof.
            $nativeDeclarations = str_contains(str_replace('\\', '/', $file->path), '/laravel/framework/src/');
            $this->mappingConfigured = CodebaseScanSyntax::query(
                $file->contents,
                self::class.($nativeDeclarations ? '::outside-class-mapping' : '::all-mapping'),
                static fn (array $nodes): bool => (new NodeFinder)->findFirst(
                    $nativeDeclarations ? self::outsideClasses($nodes) : $nodes,
                    self::knownMappingMutation(...),
                ) !== null,
            );
        } catch (\PhpParser\Error) {
            $this->scanFailed = true;
            break;
        }
    }
    if (count($this->analyzedSources) > 100_000) {
        $this->scanFailed = true;
        break;
    }
}
$this->scanComplete = $context->lastBatch && ! $this->scanFailed;
